use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let n = input["n"].as_u64().unwrap() as usize;
    let edges = input["edges"].as_array().unwrap();
    let mut graph = vec![vec![]; n];
    for edge in edges {
        let u = edge[0].as_u64().unwrap() as usize;
        let v = edge[1].as_u64().unwrap() as usize;
        graph[u].push(v);
    }

    let mut stack = Vec::new();
    let mut result = Vec::new();

    for i in 0..n {
        if graph[i].is_empty() {
            stack.push(i);
        }
    }

    while let Some(u) = stack.pop() {
        result.push(u);
        for v in &graph[u] {
            if graph[v].is_empty() {
                stack.push(v);
            }
        }
    }

    if result.is_empty() {
        Value::Null
    } else {
        Value::Array(result.into_iter().map(|v| Value::Number(v.into())).collect())
    }
}
